&lt;title&gt;Team Access Request - Action Required&lt;/title&gt;
&lt;/head&gt;
&lt;body style=""font-family: Arial, sans-serif; font-size: 14px; color: #333; line-height: 1.6;""&gt;
&lt;p&gt;Dear " &amp; local!pmName &amp; ",&lt;/p&gt;
&lt;p&gt;A new &lt;strong&gt;Team Access Request&lt;/strong&gt; has been submitted and requires your attention.&lt;/p&gt;

&lt;table style=""border-collapse: collapse; margin: 15px 0; width: 100%; max-width: 500px;""&gt;
&lt;tr style=""background-color: #f5f5f5;""&gt;
&lt;td colspan=""2"" style=""padding: 10px; font-weight: bold; border-bottom: 2px solid #ddd;""&gt;Request Details&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=""padding: 8px 15px 8px 10px; border-bottom: 1px solid #eee; width: 140px;""&gt;&lt;strong&gt;Requested By:&lt;/strong&gt;&lt;/td&gt;
&lt;td style=""padding: 8px 10px; border-bottom: 1px solid #eee;""&gt;" &amp; local!userName &amp; "&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=""padding: 8px 15px 8px 10px; border-bottom: 1px solid #eee;""&gt;&lt;strong&gt;Organization:&lt;/strong&gt;&lt;/td&gt;
&lt;td style=""padding: 8px 10px; border-bottom: 1px solid #eee;""&gt;" &amp; local!orgName &amp; "&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=""padding: 8px 15px 8px 10px; border-bottom: 1px solid #eee;""&gt;&lt;strong&gt;Team Name:&lt;/strong&gt;&lt;/td&gt;
&lt;td style=""padding: 8px 10px; border-bottom: 1px solid #eee;""&gt;" &amp; local!teamNames &amp; "&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=""padding: 8px 15px 8px 10px; vertical-align: top;""&gt;&lt;strong&gt;Requested Roles:&lt;/strong&gt;&lt;/td&gt;
&lt;td style=""padding: 8px 10px;""&gt;" &amp; local!groupNamesHtmlList &amp; "&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;

&lt;p style=""margin-top: 20px;""&gt;
&lt;a href=""" &amp; local!recordlink &amp; """ style=""background-color: #0066cc; color: white; padding: 10px 20px; text-decoration: none; border-radius: 4px; display: inline-block;""&gt;Review Request&lt;/a&gt;
&lt;/p&gt;

&lt;p style=""margin-top: 20px; color: #666;""&gt;Please review and take appropriate action on this request.&lt;/p&gt;

&lt;br&gt;
&lt;p&gt;&lt;em style=""color: #999;""&gt;This is a system generated mail. Please do not reply.&lt;/em&gt;&lt;/p&gt;
&lt;/body&gt;
&lt;/html&gt;"
)

